fn env_truthy(name: &str) -> bool {
    matches!(
        std::env::var(name).ok().as_deref(),
        Some("1") | Some("true") | Some("yes") | Some("on")
    )
}

fn scope_matches() -> bool {
    if candle_kernels::CUDA_BUILD_COMPUTE_CAP != 61 {
        return false;
    }
    let Some(expected) = candle_kernels::sm61_exact_grouped_scope::EVIDENCE_GPU_UUID else {
        return false;
    };
    std::env::var("CANDLE_ASD_TARGET_GPU_UUID").ok().as_deref() == Some(expected)
}

fn enabled() -> bool {
    scope_matches() && !env_truthy("CANDLE_SM61_EXACT_GROUPED_DISABLE")
}

fn trace_enabled() -> bool {
    env_truthy("CANDLE_SM61_EXACT_GROUPED_TRACE")
}

fn layout_ok(l: &Layout) -> bool {
    l.is_contiguous() && l.start_offset() == 0
}

fn exact_call_eligible(
    input: &CudaStorage,
    input_l: &Layout,
    kernel: &CudaStorage,
    kernel_l: &Layout,
) -> bool {
    input.dtype() == DType::F32
        && kernel.dtype() == DType::F32
        && layout_ok(input_l)
        && layout_ok(kernel_l)
        && input.device.id() == kernel.device.id()
}

fn find_conv1d(p: &ParamsConv1D) -> Option<&'static ExactDecision> {
    DECISIONS.iter().find(|d| {
        d.family == "conv"
            && d.dim == 1
            && d.batch == p.b_size
            && d.c_in == p.c_in
            && d.c_out == p.c_out
            && d.s0 == p.l_in
            && d.kernel == p.k_size
            && d.stride == p.stride
            && d.dilation == p.dilation
            && d.padding == p.padding
            && d.output_padding == 0
            && d.groups == p.groups
    })
}

