fn launch_exact(
    decision: &'static ExactDecision,
    input: &CudaStorage,
    kernel: &CudaStorage,
) -> Result<CudaStorage> {
    let ptx = candle_kernels::sm61_exact_grouped_ptx(decision.candidate_id).ok_or_else(|| {
        crate::Error::Msg(format!(
            "missing SM61 exact-grouped PTX for {}",
            decision.candidate_id
        ))
    })?;
    let dev = input.device.clone();
    let func = dev.get_or_load_custom_func(decision.entry, decision.candidate_id, ptx)?;
    let out = unsafe { dev.alloc::<f32>(decision.output_count)? };
    let cfg = LaunchConfig {
        grid_dim: (decision.grid_x, 1, 1),
        block_dim: (decision.block_x, 1, 1),
        shared_mem_bytes: 0,
    };
    let slice = match (&input.slice, &kernel.slice) {
        (S::F32(x), S::F32(w)) => {
            let mut builder = func.builder();
            builder.arg(x).arg(w).arg(&out);
            unsafe { builder.launch(cfg) }.w()?;
            S::F32(out)
        }
        _ => crate::bail!("SM61 exact-grouped internal storage dtype mismatch"),
    };
    if trace_enabled() {
        eprintln!(
            "[candle sm61 exact-grouped] geometry={} candidate={} entry={} scope=device submitted_backend=raw_exact",
            decision.geometry_id, decision.candidate_id, decision.entry,
        );
    }
    Ok(CudaStorage { slice, device: dev })
}

pub(super) fn try_launch_conv1d(
    input: &CudaStorage,
    input_l: &Layout,
    kernel: &CudaStorage,
    kernel_l: &Layout,
    p: &ParamsConv1D,
) -> Result<Option<CudaStorage>> {
    if !enabled() || !exact_call_eligible(input, input_l, kernel, kernel_l) {
        return Ok(None);
    }
    let Some(d) = find_conv1d(p) else {
        return Ok(None);
    };
    Ok(Some(launch_exact(d, input, kernel)?))
}

